#define LED_GPIO            GPIOE
#define LED_PIN             24U
#define LED_CLOCK_GATE      kCLOCK_PortE

/* -------------------------------------------------------------------------
 * Simple delay (busy-wait, calibrated for ~48 MHz IRC)
 * ------------------------------------------------------------------------- */
static void delay_ms(uint32_t ms)
{
    /* ~6000 cycles per ms at 48 MHz with a 3-cycle loop body */
    volatile uint32_t i;
    for (; ms > 0U; ms--)
    {
        for (i = 6000U; i > 0U; i--)
        {
            __asm volatile("nop");
        }
    }
}

/* -------------------------------------------------------------------------
 * LED helpers
 * ------------------------------------------------------------------------- */
