static inline void led_off(void)
{
    GPIO_PinWrite(LED_GPIO, LED_PIN, 1U);
}

static void blink_forever(uint32_t on_ms, uint32_t off_ms)
{
    for (;;)
    {
        led_on();
        delay_ms(on_ms);
        led_off();
        delay_ms(off_ms);
    }
