/* -------------------------------------------------------------------------
 * Clock configuration
 * Use internal 48 MHz IRC (HIRC) as the MCG Fast IRC, then switch to
 * BLPE or BLPI mode at 48 MHz.  The simplest safe approach for MCXC144 is
 * to enable HIRC and select it as MCGFLLCLK, keeping bus/flash clocks
 * within spec.
 *
 * We use the CLOCK_BootToHircMode() helper provided by fsl_clock for
 * MCXC144.  If your SDK revision spells it differently the equivalent
 * manual sequence is shown in comments.
 * ------------------------------------------------------------------------- */
static void board_clock_init(void)
{
    /* MCXC144: switch to HIRC (48 MHz) via the Lite MCG.
     * CLOCK_BootToHirc48MMode() is the documented MCUXpresso SDK function
     * for the Lite MCG (MCXC family). */
    const mcg_config_t mcg_cfg = {
        .mcgMode        = kMCG_ModeBLPI,
        .irclkEnableMode = kMCG_IrclkEnable,
        .ircs           = kMCG_IrcFast,   /* select 48 MHz HIRC */
        .fcrdiv         = 0U,             /* FCRDIV = 1 → 48 MHz */
        .frdiv          = 0U,
        .drs            = kMCG_DrsLow,
        .dmx32          = kMCG_Dmx32Default,
        .pll0Config     = {
            .enableMode = 0U,
            .prdiv      = 0U,
            .vdiv       = 0U,
        },
    };

    /* sim_config: run core/bus/flash at 48/24/24 MHz */
    const sim_clock_config_t sim_cfg = {
        .er32kSrc  = kSIM_OSC32kSrcOsc32k,
        .clkdiv1   = SIM_CLKDIV1_OUTDIV1(0U) | /* core  = /1 → 48 MHz */
                     SIM_CLKDIV1_OUTDIV4(1U),   /* flash = /2 → 24 MHz */
    };

    CLOCK_SetSimSafeDivs();
    CLOCK_BootToBlpiMode(mcg_cfg.fcrdiv, mcg_cfg.ircs, mcg_cfg.irclkEnableMode);
    CLOCK_SetSimConfig(&sim_cfg);
}

