    0x01, 0x02, 0x03, 0x04,
    0x05, 0x06, 0x07, 0x08,
    0x09, 0x0A, 0x0B, 0x0C,
    0x0D, 0x0E, 0x0F, 0x10
};

static flash_config_t flash_config;

/* Return true on success, false on any failure */
static bool flash_erase_write_verify(void)
{
    status_t status;
    uint32_t fail_addr;
    uint32_t fail_data;

    /* ---- 1. Initialise the flash driver ---- */
    memset(&flash_config, 0, sizeof(flash_config));
    status = FLASH_Init(&flash_config);
    if (status != kStatus_Success)
    {
        return false;
    }

    /* ---- 2. Erase the sector containing our target address ---- */
    __disable_irq();
    status = FLASH_EraseSector(&flash_config, FLASH_TARGET_ADDR,
                               flash_config.sectorSize,
                               kFLASH_ApiEraseKey);
    __enable_irq();

    if (status != kStatus_Success)
    {
        return false;
    }

    /* ---- 3. Verify the sector is erased (all 0xFF) ---- */
    __disable_irq();
    status = FLASH_VerifyEraseSector(&flash_config, FLASH_TARGET_ADDR,
                                     flash_config.sectorSize,
                                     kFLASH_MarginValueNormal);
    __enable_irq();

    if (status != kStatus_Success)
    {
        return false;
    }

    /* ---- 4. Program 16 bytes ---- */
    __disable_irq();
    status = FLASH_Program(&flash_config, FLASH_TARGET_ADDR,
                           (uint8_t *)write_data, WRITE_DATA_LEN);
    __enable_irq();

    if (status != kStatus_Success)
    {
        return false;
    }

    /* ---- 5. Verify the programmed data ---- */
    __disable_irq();
    status = FLASH_VerifyProgram(&flash_config,
                                 FLASH_TARGET_ADDR,
                                 WRITE_DATA_LEN,
                                 (const uint8_t *)write_data,
                                 kFLASH_MarginValueNormal,
                                 &fail_addr,
                                 &fail_data);
    __enable_irq();

    if (status != kStatus_Success)
    {
        return false;
    }

    /* ---- 6. Software byte-by-byte comparison ---- */
    const uint8_t *flash_ptr = (const uint8_t *)FLASH_TARGET_ADDR;
    for (uint32_t i = 0U; i < WRITE_DATA_LEN; i++)
    {
        if (flash_ptr[i] != write_data[i])
        {
            return false;
        }
    }

    return true;
