    status = FLASH_VerifyErase(&flash_config, FLASH_TARGET_ADDR, FLASH_SECTOR_SIZE, kFTFx_MarginValueNormal);
    __enable_irq();
    if (kStatus_Success != status) return false;

    __disable_irq();
    status = FLASH_Program(&flash_config, FLASH_TARGET_ADDR, (uint8_t *)(uintptr_t)write_data, WRITE_DATA_LEN);
    __enable_irq();
    if (kStatus_Success != status) return false;

    __disable_irq();
    status = FLASH_VerifyProgram(&flash_config, FLASH_TARGET_ADDR, WRITE_DATA_LEN,
                                 (const uint8_t *)write_data,
                                 kFTFx_MarginValueNormal,
                                 &fail_addr, &fail_data);
    __enable_irq();
    if (kStatus_Success != status) return false;

    const volatile uint8_t *fp = (const volatile uint8_t *)FLASH_TARGET_ADDR;
    for (uint32_t i = 0U; i < WRITE_DATA_LEN; i++)
        if (fp[i] != write_data[i]) return false;

    return true;
}

int main(void)
{
    board_clock_init();
    led_init();

    bool ok = flash_erase_write_verify();

    if (ok)
        blink_forever(100U, 100U);
    else
        blink_forever(900U, 900U);

    for (;;) {}
    return 0;
}

/*
 * Flash erase/write/verify demo for MCXC144 (Cortex-M0+)
 * Target: last sector of 128KB flash at 0x1E000
 * LED on PTE24: fast blink (100/100ms) = success, slow blink (900/900ms) = failure
 */

#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_flash.h"

/* ── Target flash region ─────────────────────────────────────────────────── */
#define FLASH_TARGET_ADDR   0x1E000UL
#define FLASH_SECTOR_SIZE   0x400UL      /* MCXC144: 1 KB sectors            */
#define WRITE_DATA_LEN      16U

/* ── LED (active-low, PTE24) ─────────────────────────────────────────────── */
#define LED_PORT            PORTE
#define LED_GPIO            GPIOE
#define LED_PIN             24U
#define LED_CLOCK_GATE      kCLOCK_PortE

/* ── Simple busy-wait delay ─────────────────────────────────────────────── */
static void delay_ms(uint32_t ms)
{
    /* ~8000 iterations ≈ 1 ms at 48 MHz with -O0; good enough for blinking */
    volatile uint32_t i;
    for (; ms > 0U; ms--)
        for (i = 8000U; i > 0U; i--)
            __asm volatile("nop");
}

/* ── LED helpers ─────────────────────────────────────────────────────────── */
static inline void led_on(void)  { GPIO_PinWrite(LED_GPIO, LED_PIN, 0U); }
static inline void led_off(void) { GPIO_PinWrite(LED_GPIO, LED_PIN, 1U); }

static void blink_forever(uint32_t on_ms, uint32_t off_ms)
{
    for (;;)
    {
        led_on();  delay_ms(on_ms);
        led_off(); delay_ms(off_ms);
    }
}

/* ── Clock init ──────────────────────────────────────────────────────────── */
static void board_clock_init(void)
{
    /*
     * MCXC144 uses MCG_Lite.  After reset it runs from HIRC (48 MHz) in
     * HIRC mode.  We just ensure the SIM clock dividers are safe:
     *   OUTDIV1 = 0  → core  = 48 MHz
     *   OUTDIV4 = 1  → flash = 24 MHz  (must be ≤ 24 MHz)
     */
    CLOCK_SetSimSafeDivs();

    /* Configure MCG Lite to stay in / switch to HIRC mode */
    mcglite_config_t cfg;
    cfg.outSrc                  = kMCGLITE_ClkSrcHirc;
    cfg.irclkEnableMode         = (uint8_t)kMCGLITE_IrclkEnable;
    cfg.fcrdiv                  = kMCGLITE_LircDivBy1;
    cfg.lircDiv2                = kMCGLITE_LircDivBy1;
    cfg.hircEnableInNotHircMode = false;

    CLOCK_SetMcgliteConfig(&cfg);

    /* Reapply dividers after clock switch */
    SIM->CLKDIV1 = SIM_CLKDIV1_OUTDIV1(0U) |
                   SIM_CLKDIV1_OUTDIV4(1U);
}

/* ── LED GPIO init ───────────────────────────────────────────────────────── */
static void led_init(void)
{
    CLOCK_EnableClock(LED_CLOCK_GATE);
    PORT_SetPinMux(LED_PORT, LED_PIN, kPORT_MuxAsGpio);

    gpio_pin_config_t pin_cfg = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = 1U,   /* start with LED off */
    };
    GPIO_PinInit(LED_GPIO, LED_PIN, &pin_cfg);
}

/* ── Flash payload ───────────────────────────────────────────────────────── */
static const uint8_t write_data[WRITE_DATA_LEN] = {
    0x01, 0x02, 0x03, 0x04,
    0x05, 0x06, 0x07, 0x08,
    0x09, 0x0A, 0x0B, 0x0C,
    0x0D, 0x0E, 0x0F, 0x10
};

static flash_config_t s_flash_config;

/* ── Flash erase / program / verify ─────────────────────────────────────── */
static bool flash_erase_write_verify(void)
{
    status_t  status;
    uint32_t  fail_addr, fail_data;

    (void)memset(&s_flash_config, 0, sizeof(s_flash_config));

    status = FLASH_Init(&s_flash_config);
    if (kStatus_Success != status)
        return false;

    /* Erase one sector */
    __disable_irq();
    status = FLASH_Erase(&s_flash_config,
                         FLASH_TARGET_ADDR,
                         FLASH_SECTOR_SIZE,
                         kFLASH_ApiEraseKey);
    __enable_irq();
    if (kStatus_Success != status)
        return false;

    /* Verify erase */
    __disable_irq();
    status = FLASH_VerifyErase(&s_flash_config,
                               FLASH_TARGET_ADDR,
                               FLASH_SECTOR_SIZE,
                               kFTFx_MarginValueNormal);
    __enable_irq();
    if (kStatus_Success != status)
        return false;

    /* Program 16 bytes */
    __disable_irq();
    status = FLASH_Program(&s_flash_config,
                           FLASH_TARGET_ADDR,
                           (uint8_t *)(uintptr_t)write_data,
                           WRITE_DATA_LEN);
    __enable_irq();
    if (kStatus_Success != status)
        return false;

    /* Verify program via FTFx read-while-verify */
    __disable_irq();
    status = FLASH_VerifyProgram(&s_flash_config,
                                 FLASH_TARGET_ADDR,
                                 WRITE_DATA_LEN,
                                 (const uint8_t *)write_data,
                                 kFTFx_MarginValueNormal,
                                 &fail_addr,
                                 &fail_data);
    __enable_irq();
    if (kStatus_Success != status)
        return false;

    /* Software byte-by-byte read-back */
    const volatile uint8_t *fp = (const volatile uint8_t *)FLASH_TARGET_ADDR;
    for (uint32_t i = 0U; i < WRITE_DATA_LEN; i++)
        if (fp[i] != write_data[i])
            return false;

    return true;
}

/* ── Entry point ─────────────────────────────────────────────────────────── */
int main(void)
{
    board_clock_init();
    led_init();

    bool ok = flash_erase_write_verify();

    if (ok)
        blink_forever(100U, 100U);   /* fast = success */
    else
        blink_forever(900U, 900U);   /* slow = failure */

    /* unreachable */
    for (;;) {}
    return 0;
}

#include <stdint.h>
#include <stdbool.h>
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_gpio.h"
#include "fsl_i2c.h"

/*******************************************************************************
 * Definitions
 ******************************************************************************/
#define I2C_PERIPHERAL       I2C0
#define I2C_BAUDRATE         100000U          /* 100 kHz                     */

/* PTC8 = SCL, PTC9 = SDA — ALT2 selects I2C0 on MCXC144                   */
#define I2C_PORT             PORTC
#define I2C_SCL_PIN          8U
#define I2C_SDA_PIN          9U
#define I2C_PIN_ALT          kPORT_MuxAlt2

/* Sensor configuration                                                        */
#define SENSOR_I2C_ADDR      0x68U            /* 7-bit address               */
#define WHO_AM_I_REG         0x75U            /* register to read            */

/* Source clock for I2C0 — connected to the bus clock (MCGIRCLK / FLL / etc.)
   MCXC144 typically runs the bus clock at 24 MHz after reset; use the same
   value the SDK clock driver reports.                                         */
#define I2C_CLOCK_FREQ       CLOCK_GetFreq(kCLOCK_BusClk)

/*******************************************************************************
 * Prototypes
 ******************************************************************************/
static void     BOARD_InitClocks(void);
static void     BOARD_InitPins(void);
static status_t I2C_ReadRegister(I2C_Type *base,
                                 uint8_t   devAddr,
                                 uint8_t   regAddr,
                                 uint8_t  *rxBuf,
                                 size_t    rxLen);

/*******************************************************************************
 * Code
 ******************************************************************************/

/**
 * @brief Enable clock gates needed for I2C0 and PORTC.
 *
 * MCXC144 uses the standard Kinetis SIM/PCC model accessed through
 * fsl_clock.h — no separate reset step is required.
 */
static void BOARD_InitClocks(void)
{
    /* Enable the clock to PORTC so we can configure the pin mux.            */
    CLOCK_EnableClock(kCLOCK_PortC);

    /* Enable the clock to I2C0.                                              */
    CLOCK_EnableClock(kCLOCK_I2c0);
}

/**
 * @brief Configure PTC8 (SCL) and PTC9 (SDA) for I2C0 alternate function.
 *
 * On MCXC144 the I2C pins require the open-drain + pull-up configuration
 * that the PORT mux field selects automatically when ALT2 is chosen for
 * the I2C function.  We also enable the internal pull-up resistor as a
 * belt-and-suspenders measure for the case where external pull-ups are
 * missing or weak.
 */
static void BOARD_InitPins(void)
{
    port_pin_config_t pinConfig = {
        .pullSelect          = kPORT_PullUp,
        .slewRate            = kPORT_SlowSlewRate,
        .passiveFilterEnable = kPORT_PassiveFilterDisable,
        .openDrainEnable     = kPORT_OpenDrainEnable,
        .driveStrength       = kPORT_LowDriveStrength,
        .mux                 = I2C_PIN_ALT,
        .lockRegister        = kPORT_UnlockRegister,
    };

    PORT_SetPinConfig(I2C_PORT, I2C_SCL_PIN, &pinConfig);
    PORT_SetPinConfig(I2C_PORT, I2C_SDA_PIN, &pinConfig);
}

/**
 * @brief Perform a single-byte register read using the blocking I2C master
 *        transfer API.
 *
 * The protocol used for most I2C sensors is:
 *   START | devAddr+W | regAddr | REPEATED-START | devAddr+R | data | STOP
 *
 * The SDK i2c_master_transfer_t structure implements this automatically when
 * subaddress fields are non-zero and the direction is kI2C_Read.
 *
 * @param base      I2C peripheral base pointer.
 * @param devAddr   7-bit slave address (not shifted).
 * @param regAddr   Register address to read from.
 * @param rxBuf     Buffer that receives the read byte(s).
 * @param rxLen     Number of bytes to read.
 * @return kStatus_Success or an I2C error code.
 */
static status_t I2C_ReadRegister(I2C_Type *base,
                                 uint8_t   devAddr,
                                 uint8_t   regAddr,
                                 uint8_t  *rxBuf,
                                 size_t    rxLen)
{
    i2c_master_transfer_t xfer;

    xfer.slaveAddress   = devAddr;
    xfer.direction      = kI2C_Read;
    xfer.subaddress     = (uint32_t)regAddr;
    xfer.subaddressSize = 1U;             /* one-byte register address       */
    xfer.data           = rxBuf;
    xfer.dataSize       = rxLen;
    xfer.flags          = kI2C_TransferDefaultFlag;

    return I2C_MasterTransferBlocking(base, &xfer);
}

/**
 * @brief Application entry point.
 */
int main(void)
{
    status_t status;
    uint8_t  whoAmI = 0U;

    /* -----------------------------------------------------------------------
     * 1. Clock setup
     * --------------------------------------------------------------------- */
    BOARD_InitClocks();

    /* -----------------------------------------------------------------------
     * 2. Pin mux setup
     * --------------------------------------------------------------------- */
    BOARD_InitPins();

    /* -----------------------------------------------------------------------
     * 3. I2C master initialisation
     * --------------------------------------------------------------------- */
    i2c_master_config_t i2cConfig;
    I2C_MasterGetDefaultConfig(&i2cConfig);

    /* Override the baud rate; all other defaults are acceptable.             */
    i2cConfig.baudRate_Bps = I2C_BAUDRATE;

    /* I2C_CLOCK_FREQ expands to a CLOCK_GetFreq() call — evaluated here so
       the correct run-time value is passed to the init function.             */
    uint32_t i2cClockFreq = I2C_CLOCK_FREQ;
    I2C_MasterInit(I2C_PERIPHERAL, &i2cConfig, i2cClockFreq);

    /* -----------------------------------------------------------------------
     * 4. Read WHO_AM_I register (0x75) from sensor at address 0x68
     * --------------------------------------------------------------------- */
    status = I2C_ReadRegister(I2C_PERIPHERAL,
                              SENSOR_I2C_ADDR,
                              WHO_AM_I_REG,
                              &whoAmI,
                              1U);

    /* -----------------------------------------------------------------------
     * 5. Error handling
     *
     * In a production application you would log or signal the error.  Here
     * we spin in a distinct loop so a debugger can distinguish the success
     * path from the failure path by inspecting the PC.
     * --------------------------------------------------------------------- */
    if (status != kStatus_Success)
    {
        /* Communication failure — recover the bus and halt.                  */
        I2C_MasterDeinit(I2C_PERIPHERAL);

        /* Re-initialise so the bus is left in a clean idle state before
           the infinite loop, which allows a debugger to restart the app.     */
        I2C_MasterInit(I2C_PERIPHERAL, &i2cConfig, i2cClockFreq);

        /* Hang here; whoAmI retains 0 to indicate an invalid result.        */
        while (true)
        {
            /* Error: I2C transfer failed.
               Inspect 'status' in a debugger for the exact error code:
                 kStatus_I2C_Nak          — slave not acknowledging
                 kStatus_I2C_ArbitrationLost — bus contention
                 kStatus_I2C_Timeout      — bus hung / no pull-ups
            */
        }
    }

    /* -----------------------------------------------------------------------
     * 6. Success — whoAmI now holds the sensor's WHO_AM_I response.
     *    For an MPU-6050 / MPU-6500 at address 0x68 the expected value
     *    is 0x68 (MPU-6050) or 0x70 (MPU-6500).
     * --------------------------------------------------------------------- */
    (void)whoAmI;   /* suppress unused-variable warning; use value here      */

    while (true)
    {
        /* Main application loop.
           'whoAmI' contains the register value read from the sensor.        */
    }

    return 0;
}

#include <stdint.h>
#include <stdbool.h>
#include "fsl_clock.h"
#include "fsl_port.h"
#include "fsl_i2c.h"

/*******************************************************************************
