#define I2C_BAUDRATE         100000U          /* 100 kHz                     */

/* PTC8 = SCL, PTC9 = SDA — ALT2 selects I2C0 on MCXC144                   */
#define I2C_PORT             PORTC
#define I2C_SCL_PIN          8U
#define I2C_SDA_PIN          9U
#define I2C_PIN_ALT          kPORT_MuxAlt2

/* Sensor configuration                                                        */
#define SENSOR_I2C_ADDR      0x68U            /* 7-bit address               */
#define WHO_AM_I_REG         0x75U            /* register to read            */

/*******************************************************************************
 * Prototypes
 ******************************************************************************/
static void     BOARD_InitClocks(void);
static void     BOARD_InitPins(void);
static status_t I2C_ReadRegister(I2C_Type *base,
                                 uint8_t   devAddr,
                                 uint8_t   regAddr,
                                 uint8_t  *rxBuf,
                                 size_t    rxLen);

/*******************************************************************************
 * Code
 ******************************************************************************/

/**
 * @brief Enable clock gates needed for I2C0 and PORTC.
 */
static void BOARD_InitClocks(void)
{
    /* Enable the clock to PORTC so we can configure the pin mux. */
    CLOCK_EnableClock(kCLOCK_PortC);

    /* Enable the clock to I2C0. */
    CLOCK_EnableClock(kCLOCK_I2c0);
}

/**
 * @brief Configure PTC8 (SCL) and PTC9 (SDA) for I2C0 alternate function.
 *
 * PORT_SetPinMux sets only the MUX field in PCR, leaving all other fields
 * at their reset values.  This avoids using port_pin_config_t fields that
 * are not present on the MCXC144 variant of the PORT peripheral
 * (e.g. openDrainEnable, lockRegister).
 */
static void BOARD_InitPins(void)
{
    PORT_SetPinMux(I2C_PORT, I2C_SCL_PIN, I2C_PIN_ALT);
    PORT_SetPinMux(I2C_PORT, I2C_SDA_PIN, I2C_PIN_ALT);
}

/**
 * @brief Perform a single-byte register read using the blocking I2C master
 *        transfer API.
 *
 * Protocol:
 *   START | devAddr+W | regAddr | REPEATED-START | devAddr+R | data | STOP
 *
 * @param base      I2C peripheral base pointer.
 * @param devAddr   7-bit slave address (not shifted).
 * @param regAddr   Register address to read from.
 * @param rxBuf     Buffer that receives the read byte(s).
 * @param rxLen     Number of bytes to read.
 * @return kStatus_Success or an I2C error code.
 */
static status_t I2C_ReadRegister(I2C_Type *base,
                                 uint8_t   devAddr,
                                 uint8_t   regAddr,
                                 uint8_t  *rxBuf,
                                 size_t    rxLen)
{
    i2c_master_transfer_t xfer;

    xfer.slaveAddress   = devAddr;
    xfer.direction      = kI2C_Read;
    xfer.subaddress     = (uint32_t)regAddr;
    xfer.subaddressSize = 1U;             /* one-byte register address       */
    xfer.data           = rxBuf;
    xfer.dataSize       = rxLen;
    xfer.flags          = kI2C_TransferDefaultFlag;

    return I2C_MasterTransferBlocking(base, &xfer);
}

/**
 * @brief Application entry point.
 */
int main(void)
{
    status_t status;
    uint8_t  whoAmI = 0U;

    /* -----------------------------------------------------------------------
     * 1. Clock setup
     * --------------------------------------------------------------------- */
    BOARD_InitClocks();

    /* -----------------------------------------------------------------------
     * 2. Pin mux setup
     * --------------------------------------------------------------------- */
    BOARD_InitPins();

    /* -----------------------------------------------------------------------
     * 3. I2C master initialisation
     * --------------------------------------------------------------------- */
    i2c_master_config_t i2cConfig;
    I2C_MasterGetDefaultConfig(&i2cConfig);

    /* Override the baud rate; all other defaults are acceptable. */
    i2cConfig.baudRate_Bps = I2C_BAUDRATE;

    /* Evaluate CLOCK_GetFreq() at runtime so the correct bus clock frequency
       is passed to the init function. */
    uint32_t i2cClockFreq = CLOCK_GetFreq(kCLOCK_BusClk);
    I2C_MasterInit(I2C_PERIPHERAL, &i2cConfig, i2cClockFreq);

    /* -----------------------------------------------------------------------
     * 4. Read WHO_AM_I register (0x75) from sensor at address 0x68
     * --------------------------------------------------------------------- */
    status = I2C_ReadRegister(I2C_PERIPHERAL,
                              SENSOR_I2C_ADDR,
                              WHO_AM_I_REG,
                              &whoAmI,
                              1U);

    /* -----------------------------------------------------------------------
     * 5. Error handling
     *
     * In a production application you would log or signal the error.  Here
     * we spin so a debugger can distinguish success from failure by
     * inspecting the PC and the 'status' variable.
     *
     * Possible error codes:
     *   kStatus_I2C_Nak            — slave not acknowledging (wrong address
     *                                or sensor not present)
     *   kStatus_I2C_ArbitrationLost — bus contention
     *   kStatus_I2C_Timeout        — bus hung (missing pull-ups, etc.)
     * --------------------------------------------------------------------- */
    if (status != kStatus_Success)
    {
        /* Attempt to release the bus cleanly before halting. */
        I2C_MasterDeinit(I2C_PERIPHERAL);
        I2C_MasterInit(I2C_PERIPHERAL, &i2cConfig, i2cClockFreq);

        /* whoAmI retains 0 to indicate an invalid / unread value. */
        while (true)
        {
            /* Halted on error — inspect 'status' in the debugger. */
        }
    }

    /* -----------------------------------------------------------------------
     * 6. Success — whoAmI now holds the sensor's WHO_AM_I response.
     *    For an MPU-6050 at address 0x68 the expected value is 0x68.
     *    For an MPU-6500 the expected value is 0x70.
     * --------------------------------------------------------------------- */
    (void)whoAmI;   /* Use or display whoAmI here in a real application. */

    while (true)
    {
        /* Main application loop.
           'whoAmI' contains the WHO_AM_I register value from the sensor. */
    }

    return 0;
}

/*
 * bare_metal_pit_gpio.c
 *
 * Bare-metal NXP MCUXpresso SDK application for MCXC144 (Cortex-M0+).
 *
 * - PIT channel 0 fires every 10 ms (48 MHz bus clock).
 * - ISR reads PTC3 (digital input) and sets a flag for the main loop.
 * - Main loop detects the flag, clears it atomically, and toggles PTE24
 *   (LED) when the sampled pin is high.
 *
 * Race-condition safety:
 *   - g_sampleReady is volatile uint8_t; written once to 1 by the ISR,
 *     cleared to 0 by main AFTER copying g_sampleValue.
 *   - g_sampleValue is volatile uint8_t; written by ISR before the flag
 *     is raised, read by main only after the flag is observed.
 *   - On Cortex-M0+ all byte/word accesses are atomic, so a single-byte
 *     flag is sufficient.  The compiler ordering is enforced by the
 *     volatile qualifier on both variables.
 */

#include <stdint.h>

/* SDK driver headers — bring in device definitions transitively */
#include "fsl_clock.h"   /* CLOCK_EnableClock, clock gating               */
#include "fsl_port.h"    /* PORT_SetPinMux                                 */
#include "fsl_gpio.h"    /* GPIO_PinInit, GPIO_PinRead, GPIO_PortToggle    */
#include "fsl_pit.h"     /* PIT_Init, PIT_SetTimerPeriod, PIT_StartTimer   */

/* -----------------------------------------------------------------------
 * Hardware constants
 * --------------------------------------------------------------------- */

/* Bus / core clock assumed to be 48 MHz (FLL default after reset on
 * MCXC144; adjust CLOCK_CONFIG if a different source is used).          */
#define CORE_CLOCK_HZ   48000000U
#define BUS_CLOCK_HZ    48000000U   /* PIT is clocked from the bus clock  */

/* PIT period = 10 ms */
#define PIT_PERIOD_MS   10U
#define PIT_LOAD_VALUE  ((BUS_CLOCK_HZ / 1000U) * PIT_PERIOD_MS - 1U)

/* Digital input: PTC3 */
#define INPUT_PORT      PORTC
#define INPUT_GPIO      GPIOC
#define INPUT_PIN       3U

/* LED output: PTE24 */
#define LED_PORT        PORTE
#define LED_GPIO        GPIOE
#define LED_PIN         24U

/* -----------------------------------------------------------------------
 * ISR ↔ main shared state (volatile for compiler ordering + visibility)
 * --------------------------------------------------------------------- */
static volatile uint8_t g_sampleReady = 0U;  /* 1 = new sample available  */
static volatile uint8_t g_sampleValue = 0U;  /* last sampled pin value     */

/* -----------------------------------------------------------------------
 * PIT channel 0 ISR
 * --------------------------------------------------------------------- */
void PIT_IRQHandler(void)
{
    /* Clear the interrupt flag first to re-arm the timer */
    PIT_ClearStatusFlags(PIT, kPIT_Chnl_0, kPIT_TimerFlag);

    /* Sample the digital input.  Write value BEFORE setting the flag so
     * the main loop always sees a consistent pair. */
    g_sampleValue = (uint8_t)GPIO_PinRead(INPUT_GPIO, INPUT_PIN);

    /* Signal the main loop */
    g_sampleReady = 1U;
}

/* -----------------------------------------------------------------------
 * Clock configuration
 *
 * MCXC144 starts up with the Multipurpose Clock Generator (MCG) in FEI
 * mode using the 32 kHz internal reference multiplied to 48 MHz via the
 * FLL.  The default SystemCoreClock is already 48 MHz on most MCUXpresso
 * SDK BSPs, so we only need to enable peripheral clock gates here.
 * --------------------------------------------------------------------- */
static void BOARD_InitClocks(void)
{
    /* Port clock gates */
    CLOCK_EnableClock(kCLOCK_PortC);   /* PTC3  */
    CLOCK_EnableClock(kCLOCK_PortE);   /* PTE24 */

    /* PIT clock gate */
    CLOCK_EnableClock(kCLOCK_Pit0);
}

/* -----------------------------------------------------------------------
 * Pin-mux + GPIO initialisation
 * --------------------------------------------------------------------- */
static void BOARD_InitPins(void)
{
    /* PTC3 — digital input, no pull (external pull assumed) */
    PORT_SetPinMux(INPUT_PORT, INPUT_PIN, kPORT_MuxAsGpio);

    gpio_pin_config_t inputCfg = {
        .pinDirection = kGPIO_DigitalInput,
        .outputLogic  = 0U
    };
    GPIO_PinInit(INPUT_GPIO, INPUT_PIN, &inputCfg);

    /* PTE24 — digital output, start with LED off (logic 1 = off for
     * common active-low LED; change outputLogic to 0 for active-high) */
    PORT_SetPinMux(LED_PORT, LED_PIN, kPORT_MuxAsGpio);

    gpio_pin_config_t ledCfg = {
        .pinDirection = kGPIO_DigitalOutput,
        .outputLogic  = 1U   /* LED off initially */
    };
    GPIO_PinInit(LED_GPIO, LED_PIN, &ledCfg);
}

/* -----------------------------------------------------------------------
 * PIT initialisation
 * --------------------------------------------------------------------- */
static void BOARD_InitPIT(void)
{
    pit_config_t pitConfig;
    PIT_GetDefaultConfig(&pitConfig);
    /* pitConfig.enableRunInDebug defaults to false — acceptable */
    PIT_Init(PIT, &pitConfig);

    /* Load the 10 ms period */
    PIT_SetTimerPeriod(PIT, kPIT_Chnl_0, (uint32_t)PIT_LOAD_VALUE);

    /* Enable channel 0 interrupt in the PIT peripheral */
    PIT_EnableInterrupts(PIT, kPIT_Chnl_0, kPIT_TimerInterruptEnable);

    /* Enable PIT IRQ in the NVIC — Cortex-M0+ uses NVIC_SetPriority /
     * EnableIRQ from CMSIS core_cm0plus.h (pulled in via fsl_common.h). */
    NVIC_SetPriority(PIT_IRQn, 2U);
    EnableIRQ(PIT_IRQn);

    /* Start the timer */
    PIT_StartTimer(PIT, kPIT_Chnl_0);
}

/* -----------------------------------------------------------------------
 * Main
 * --------------------------------------------------------------------- */
int main(void)
{
    BOARD_InitClocks();
    BOARD_InitPins();
    BOARD_InitPIT();

    for (;;)
    {
        /* Poll the flag set by the ISR */
        if (g_sampleReady != 0U)
        {
            /* Copy the sample value before clearing the flag so the ISR
             * cannot overwrite g_sampleValue while we are still using it.
             * On Cortex-M0+ a byte read is atomic, so no critical section
             * is needed for the uint8_t variables themselves.              */
            uint8_t sample = g_sampleValue;

            /* Clear the flag — the ISR will not write g_sampleValue again
             * until it next fires, which is at least one full period away. */
            g_sampleReady = 0U;

            /* If the sampled pin was high, toggle the LED */
            if (sample != 0U)
            {
                GPIO_PortToggle(LED_GPIO, (1U << LED_PIN));
            }
        }

        /* Low-power wait: sleep until the next interrupt wakes us.
         * __WFI() is a CMSIS intrinsic available on all Cortex-M cores.  */
        __WFI();
    }

    /* Unreachable */
    return 0;
}

