/*
 * Bare-metal UART0 "Hello\r\n" transmit loop for MCXC144 (Cortex-M0+)
 * MCUXpresso SDK driver headers only — no board/pin_mux/clock_config files.
 *
 * Hardware connections:
 *   PTA1 -> UART0_RX  (ALT2)
 *   PTA2 -> UART0_TX  (ALT2)
 */

#include <stdint.h>
#include <stddef.h>

#include "fsl_clock.h"   /* CLOCK_EnableClock, clock gating symbols        */
#include "fsl_port.h"    /* PORT_SetPinMux, port_mux_t                     */
#include "fsl_gpio.h"    /* (included for completeness; not used directly)  */
#include "fsl_uart.h"    /* UART_GetDefaultConfig, UART_Init, UART_WriteBlocking */

/* -------------------------------------------------------------------------
 * Clock / peripheral constants
 * ---------------------------------------------------------------------- */

/*
 * MCXC144 ROM trims the FLL to 48 MHz when the device boots from internal
 * clock (FEI mode, MCGFLLCLK = 48 MHz, UART0SRC = MCGFLLCLK).
 * UART0 on this device uses a dedicated clock selector (SIM_SOPT2[UART0SRC]).
 * We select MCGFLLCLK (48 MHz) as the UART0 clock source.
 *
 * SIM_SOPT2 bit-field UART0SRC = 0b01  →  MCGFLLCLK / MCGPLLCLK/2
 */
#define UART0_CLKSRC_HZ     (48000000UL)   /* MCGFLLCLK after reset        */
#define UART0_BAUD          (115200UL)

/* -------------------------------------------------------------------------
 * Tiny software delay (~1 second at 48 MHz Cortex-M0+, -O0)
 * Each loop iteration costs roughly 4 cycles (M0+ 2-cycle branch + 2 ops).
 * Adjust the count if the optimisation level changes.
 * ---------------------------------------------------------------------- */
static void delay_1s(void)
{
    /*
     * 48 000 000 Hz / 4 cycles per iteration ≈ 12 000 000 iterations
     * Use volatile so the loop is not optimised away.
     */
    volatile uint32_t count = 12000000UL;
    while (count--)
    {
        __asm volatile ("nop");
    }
}

/* -------------------------------------------------------------------------
 * main
 * ---------------------------------------------------------------------- */
int main(void)
{
    /* ------------------------------------------------------------------
     * 1.  Clock gating
     *     Enable clocks for PORTA, UART0, and select the UART0 clock source.
     * ------------------------------------------------------------------ */

    /*
     * Select UART0 clock source = MCGFLLCLK (bits [27:26] = 0b01).
     * SIM_SOPT2 is accessible through the SIM peripheral base pointer that
     * fsl_clock.h / the device header expose.
     */
    SIM->SOPT2 = (SIM->SOPT2 & ~SIM_SOPT2_UART0SRC_MASK) |
                  SIM_SOPT2_UART0SRC(1U);   /* 1 = MCGFLLCLK              */

    /* Gate on PORTA (for pin-mux) and UART0 */
    CLOCK_EnableClock(kCLOCK_PortA);
    CLOCK_EnableClock(kCLOCK_Uart0);

    /* ------------------------------------------------------------------
     * 2.  Pin mux  — PTA1 = ALT2 (UART0_RX), PTA2 = ALT2 (UART0_TX)
     * ------------------------------------------------------------------ */
    PORT_SetPinMux(PORTA, 1U, kPORT_MuxAlt2);  /* PTA1 → UART0_RX */
    PORT_SetPinMux(PORTA, 2U, kPORT_MuxAlt2);  /* PTA2 → UART0_TX */

    /* ------------------------------------------------------------------
     * 3.  UART0 initialisation — 115200 8N1
     * ------------------------------------------------------------------ */
    uart_config_t uartConfig;
    UART_GetDefaultConfig(&uartConfig);          /* fills sensible defaults  */

    uartConfig.baudRate_Bps = UART0_BAUD;
    uartConfig.enableTx     = true;
    uartConfig.enableRx     = true;
    /* parityMode, stopBitCount, dataBitsCount already 8N1 in default cfg    */

    status_t status = UART_Init(UART0, &uartConfig, UART0_CLKSRC_HZ);
    if (status != kStatus_Success)
    {
        /* Could not configure baud — spin here so a debugger can catch it  */
        while (1)
        {
            __asm volatile ("nop");
        }
    }

    /* ------------------------------------------------------------------
     * 4.  Main loop — transmit "Hello\r\n" every second
     * ------------------------------------------------------------------ */
    const uint8_t message[]  = "Hello\r\n";
    const size_t  msgLength  = sizeof(message) - 1U;   /* exclude NUL      */

    while (1)
    {
        /* UART_WriteBlocking blocks until every byte has shifted out       */
        UART_WriteBlocking(UART0, message, msgLength);

        delay_1s();
    }

    /* Unreachable */
    return 0;
}

