/*
 * eDMA memory-to-memory copy example for i.MX RT1170 (MIMXRT1176, Cortex-M7)
 * Uses MCUXpresso SDK fsl_edma.h driver.
 *
 * No board.h / pin_mux.h / clock_config.h dependencies.
 */

#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_edma.h"

/* -------------------------------------------------------------------------
 * Configuration
 * ------------------------------------------------------------------------- */
#define TRANSFER_SIZE   512U        /* bytes to copy                        */
#define DMA_BASE        DMA0        /* eDMA controller                      */
#define DMA_CHANNEL     0U          /* channel 0                            */
#define DMAMUX_BASE     DMAMUX0     /* DMAMUX attached to DMA0              */

/* -------------------------------------------------------------------------
 * Buffers – place in non-cached RAM (DTCM on RT1170) or add cache
 * maintenance.  DTCM is used by default when linked to the DTCM region.
 * AT_NONCACHEABLE_SECTION macro is defined in fsl_common.h for SDK targets
 * that use cached memory; it expands to an appropriate section attribute.
 * Using it here keeps the example safe on all memory configurations.
 * ------------------------------------------------------------------------- */
AT_NONCACHEABLE_SECTION_ALIGN(static uint8_t s_srcBuf[TRANSFER_SIZE], 32U);
AT_NONCACHEABLE_SECTION_ALIGN(static uint8_t s_dstBuf[TRANSFER_SIZE], 32U);

/* -------------------------------------------------------------------------
 * Transfer-done flag – written from the callback (ISR context)
 * ------------------------------------------------------------------------- */
static volatile bool s_transferDone = false;

/* -------------------------------------------------------------------------
 * eDMA callback
 * ------------------------------------------------------------------------- */
static void edma_callback(edma_handle_t *handle,
                          void          *userData,
                          bool           transferDone,
                          uint32_t       tcds)
{
    (void)handle;
    (void)userData;
    (void)tcds;

    if (transferDone)
    {
        s_transferDone = true;
    }
}

/* -------------------------------------------------------------------------
 * Clock initialisation
 *
 * RT1170 runs from the on-chip RC oscillator after reset.
 * For a self-contained demo we only need the eDMA clock, which is part of
 * the bus/AIPS fabric that is clocked by default.  We call
 * CLOCK_EnableClock to be explicit and satisfy the SDK requirement.
 * ------------------------------------------------------------------------- */
static void clock_init(void)
{
    /* eDMA and DMAMUX clocks are gated under the M7 clock domain.
     * On RT1170 these are always-on after reset, but enabling explicitly
     * is the correct SDK idiom. */
    CLOCK_EnableClock(kCLOCK_Dma);       /* DMA0 clock gate                */
}

/* -------------------------------------------------------------------------
 * main
 * ------------------------------------------------------------------------- */
int main(void)
{
    /* -- 1. Clock gating -------------------------------------------------- */
    clock_init();

    /* -- 2. Fill source buffer with (index & 0xFF) ------------------------ */
    for (uint32_t i = 0U; i < TRANSFER_SIZE; i++)
    {
        s_srcBuf[i] = (uint8_t)(i & 0xFFU);
    }
    memset(s_dstBuf, 0, TRANSFER_SIZE);

    /* -- 3. Initialise eDMA controller ------------------------------------ */
    edma_config_t dmaConfig;
    EDMA_GetDefaultConfig(&dmaConfig);
    /* Default: round-robin arbitration disabled, debug stall disabled.
     * No changes needed for a simple memory copy. */
    EDMA_Init(DMA_BASE, &dmaConfig);

    /* -- 4. Create an eDMA handle for channel 0 --------------------------- */
    edma_handle_t dmaHandle;
    EDMA_CreateHandle(&dmaHandle, DMA_BASE, DMA_CHANNEL);

    /* -- 5. Set the callback ----------------------------------------------- */
    EDMA_SetCallback(&dmaHandle, edma_callback, NULL);

    /* -- 6. Prepare the transfer configuration ---------------------------- */
    edma_transfer_config_t xferConfig;

    EDMA_PrepareTransfer(
        &xferConfig,
        (void *)s_srcBuf,               /* source address                   */
        sizeof(uint8_t),                /* source width  (1 byte)           */
        (void *)s_dstBuf,               /* destination address              */
        sizeof(uint8_t),                /* destination width (1 byte)       */
        TRANSFER_SIZE,                  /* minor loop / bytes per request   */
        TRANSFER_SIZE,                  /* total bytes                      */
        kEDMA_MemoryToMemory            /* transfer type                    */
    );

    /* -- 7. Submit the transfer ------------------------------------------- */
    status_t status = EDMA_SubmitTransfer(&dmaHandle, &xferConfig);
    if (status != kStatus_Success)
    {
        /* Submission failed – halt */
        while (true)
        {
            __NOP();
        }
    }

    /* -- 8. Start the transfer -------------------------------------------- */
    EDMA_StartTransfer(&dmaHandle);

    /* For memory-to-memory transfers the hardware auto-requests; no DMAMUX
     * channel source is needed (the channel request is always enabled). */

    /* -- 9. Wait for completion ------------------------------------------- */
    while (!s_transferDone)
    {
        __NOP();
    }

    /* -- 10. Verify -------------------------------------------------------- */
    for (uint32_t i = 0U; i < TRANSFER_SIZE; i++)
    {
        if (s_dstBuf[i] != s_srcBuf[i])
        {
            /* Mismatch – halt */
            while (true)
            {
                __NOP();
            }
        }
    }

    /* Transfer verified successfully – halt normally */
    while (true)
    {
        __NOP();
    }

    return 0;
}

