 * Clock initialisation
 * ------------------------------------------------------------------------- */
static void clock_init(void)
{
    /* Enable the eDMA clock gate. kCLOCK_Edma is the correct enumerator
     * on RT1170 SDK. */
    CLOCK_EnableClock(kCLOCK_Edma);
}

/* -------------------------------------------------------------------------
 * main
 * ------------------------------------------------------------------------- */
int main(void)
{
    /* -- 1. Clock gating -------------------------------------------------- */
    clock_init();

    /* -- 2. Fill source buffer with (index & 0xFF) ------------------------ */
    for (uint32_t i = 0U; i < TRANSFER_SIZE; i++)
    {
        s_srcBuf[i] = (uint8_t)(i & 0xFFU);
    }
    memset(s_dstBuf, 0, TRANSFER_SIZE);

    /* -- 3. Initialise eDMA controller ------------------------------------ */
    edma_config_t dmaConfig;
    EDMA_GetDefaultConfig(&dmaConfig);
    EDMA_Init(DMA_BASE, &dmaConfig);

    /* -- 4. Create an eDMA handle for channel 0 --------------------------- */
    edma_handle_t dmaHandle;
    EDMA_CreateHandle(&dmaHandle, DMA_BASE, DMA_CHANNEL);

    /* -- 5. Set the callback ----------------------------------------------- */
    EDMA_SetCallback(&dmaHandle, dma_transfer_callback, NULL);

    /* -- 6. Prepare the transfer configuration ---------------------------- */
    edma_transfer_config_t xferConfig;

    EDMA_PrepareTransfer(
        &xferConfig,
        (void *)s_srcBuf,               /* source address                   */
        sizeof(uint8_t),                /* source transfer width (1 byte)   */
        (void *)s_dstBuf,               /* destination address              */
        sizeof(uint8_t),                /* destination transfer width       */
        TRANSFER_SIZE,                  /* minor loop bytes (per request)   */
        TRANSFER_SIZE,                  /* total bytes                      */
        kEDMA_MemoryToMemory            /* transfer type                    */
    );

    /* -- 7. Submit the transfer ------------------------------------------- */
    status_t status = EDMA_SubmitTransfer(&dmaHandle, &xferConfig);
    if (status != kStatus_Success)
    {
        /* Submission failed – halt */
        while (true)
        {
            __NOP();
        }
    }

    /* -- 8. Start the transfer -------------------------------------------- */
    EDMA_StartTransfer(&dmaHandle);

    /* For memory-to-memory transfers the hardware auto-requests via the
     * always-on request; no DMAMUX source assignment is required. */

    /* -- 9. Wait for completion ------------------------------------------- */
    while (!s_transferDone)
    {
        __NOP();
    }

    /* -- 10. Verify -------------------------------------------------------- */
    for (uint32_t i = 0U; i < TRANSFER_SIZE; i++)
    {
        if (s_dstBuf[i] != s_srcBuf[i])
        {
            /* Mismatch – halt */
            while (true)
            {
                __NOP();
            }
        }
    }

    /* Transfer verified successfully – halt normally */
    while (true)
    {
        __NOP();
    }

    return 0;
}

/*
 * Bare-metal LED blink for i.MX RT1170 (MIMXRT1176, Cortex-M7)
 * LED: GPIO9 pin 3, pad GPIO_AD_04
 * SDK headers only — no board.h / pin_mux.h / clock_config.h
 */

#include <stdint.h>
#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_gpio.h"

/* ------------------------------------------------------------------ */
/* Delay                                                                */
/* ------------------------------------------------------------------ */

/*
 * The Cortex-M7 on RT1176 typically runs at 600 MHz after PLL init.
 * We have not configured the PLLs here, so the core runs on the
 * internal RC oscillator (24 MHz after ROM boot).  Tune the loop
 * count so that one call ≈ 500 ms at 24 MHz.
 *
 * At 24 MHz, 500 ms ≈ 12 000 000 cycles.
 * The inner loop body is ~3 cycles (branch + decrement) on M7 with
 * cache off, so count ≈ 4 000 000.
 */
#define DELAY_LOOP_COUNT  (4000000UL)

static void SoftwareDelay(volatile uint32_t count)
{
    while (count--)
    {
        __NOP();
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- 1. Clock gate for GPIO9 ---------------------------------- */
    /*
     * GPIO9 is in the LPSR domain.  The clock gate symbol on RT1170
     * SDK is kCLOCK_Gpio9.
     */
    CLOCK_EnableClock(kCLOCK_Gpio9);

    /* ---- 2. Pin mux: GPIO_AD_04 → GPIO9_IO03 ---------------------- */
    /*
     * IOMUXC_SetPinMux(muxRegister, muxMode, inputReg, inputDaisy,
     *                  configRegister, inputOnField)
     *
     * For GPIO_AD_04 on RT1176:
     *   MUX_MODE = ALT0  → GPIO9_IO03  (value 5 in some packs; check
     *   the reference manual.  RT1170 RM Table "IOMUXC_SW_MUX_CTL_PAD_
     *   GPIO_AD_04" lists ALT5 = GPIO9_IO03.)
     *
     * We use the constants provided by fsl_iomuxc.h which are generated
     * from the silicon data and have the form:
     *   IOMUXC_GPIO_AD_04_GPIO9_IO03
     * That macro expands to the four register/field arguments.
     */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_04_GPIO9_IO03,   /* mux register + mode          */
        0U);                            /* inputOnField = 0 (no daisy)  */

    /*
     * Pad configuration: slow slew, drive strength R0/2, pull-down
     * disabled, no keeper, no open-drain.  We just need a plain
     * push-pull output so accept near-defaults; enable the pull-up
     * to avoid floating while the pin is configured.
     *
     * IOMUXC_SetPinConfig(muxReg, muxMode, inputReg, inputDaisy,
     *                     configReg, configValue)
     *
     * Bit fields for the pad config register (SW_PAD_CTL):
     *   [0]    SRE  = 0  slow slew rate
     *   [3:1]  DSE  = 110b (R0/2) → 0x6 drive strength
     *   [5:4]  SPEED (not on RT1170; reserved, write 0)
     *   [11]   ODE  = 0  push-pull
     *   [12]   PKE  = 1  pull/keeper enable
     *   [13]   PUE  = 1  pull (not keeper)
     *   [15:14] PUS = 00 100k pull-down  → we want pull-up: 11 = 22k pull-up
     *   [16]   HYS  = 0
     *
     * A safe value: 0x0000B0A0u
     *   DSE=110(0x6)→bits[3:1]=110→0x0C, SRE=0
     *   PKE=1→bit12, PUE=1→bit13, PUS=11→bits[15:14]=0xC000
     *   = 0xC000 | 0x000C = 0xC00C
     *
     * We keep it simple and use a commonly documented "default GPIO
     * output" value from RT1170 examples: 0x0000B0A0
     *   [3:1]=100 (DSE R0/4), PKE=1, PUE=1, PUS=10 (100k pull-up)
     */
    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_04_GPIO9_IO03,
        0x0000B0A0U);

    /* ---- 3. GPIO pin configuration -------------------------------- */
    gpio_pin_config_t ledConfig = {
        .direction     = kGPIO_DigitalOutput,
        .outputLogic   = 0U,    /* LED off at startup (logic 0) */
        .interruptMode = kGPIO_NoIntmode
    };

    GPIO_PinInit(GPIO9, 3U, &ledConfig);

    /* ---- 4. Blink loop -------------------------------------------- */
    for (;;)
    {
        /* Toggle LED */
        GPIO_PortToggle(GPIO9, (1UL << 3U));

        /* ~500 ms delay */
        SoftwareDelay(DELAY_LOOP_COUNT);
    }

    /* Never reached */
    return 0;
}

