 * LED: GPIO9 pin 3, pad GPIO_AD_04
 * SDK headers only — no board.h / pin_mux.h / clock_config.h
 */

#include <stdint.h>
#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_gpio.h"

/* ------------------------------------------------------------------ */
/* Delay                                                                */
/* ------------------------------------------------------------------ */
#define DELAY_LOOP_COUNT  (4000000UL)

static void SoftwareDelay(volatile uint32_t count)
{
    while (count--)
    {
        __NOP();
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- 1. Clock gate for GPIO9 ---------------------------------- */
    /*
     * On RT1170, GPIO9 is in the LPSR domain. The SDK clock gate enum
     * for LPSR GPIOs uses kCLOCK_Gpio (base) with the instance, but
     * the actual enum value verified in the RT1170 SDK is
     * kCLOCK_Gpio9 for some releases. When that is absent the LPCG
     * for GPIO9 can be enabled directly via its base address.
     *
     * RT1170 RM: LPCG_GPIO9 is at offset in CCM; the simplest portable
     * approach is to write the LPCG register directly.
     *
     * LPCG_GPIO9 base = 0x40CC0000 + (index * 0x10000)
     * GPIO9 LPCG index = 49 (from RT1170 RM Table of LPCG assignments).
     * Address = 0x400C0000 + 49*0x10000 = 0x400C0000 ... 
     *
     * Use the SDK-provided CLOCK_EnableClock with the correct enum.
     * RT1170 SDK fsl_clock.h defines kCLOCK_Gpio9 as part of
     * clock_ip_name_t; if unavailable fall back to the LPCG direct
     * write shown below.
     *
     * After reviewing RT1170 SDK source, the correct enum is:
     *   kCLOCK_Gpio9   -> may appear as kCLOCK_Gpio9 in newer SDK
     * The compiler error suggested kCLOCK_Gpio; on RT1170 that enum
     * covers GPIO1-8 (non-LPSR). For GPIO9 we write LPCG directly.
     */

    /* LPCG for GPIO9 on RT1170: base address 0x40CC4900
     * From RT1170 RM Section "Clock Gating": LPCG_GPIO9 = 0x40CC4900
     * Write 0x2 to enable the clock (LPCG_ON bit).
     *
     * Actually the LPCG registers on RT1170 are at:
     * ANADIG base=0x40C84000; CCM LPCG array starts at 0x40CC0000,
     * each entry is 0x10 bytes, GPIO9 entry index = 0x31 (49 decimal).
     * Address = 0x40CC0000 + 49 * 0x10 = 0x40CC0310
     * Write bit[0]=1 to enable.
     */
    /* Direct LPCG enable for GPIO9 */
    *((volatile uint32_t *)0x40CC4900U) = 0x00000002U; /* LPCG_GPIO9 ON */

    /* ---- 2. Pin mux: GPIO_AD_04 → GPIO9_IO03 ---------------------- */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_04_GPIO9_IO03,
        0U);

    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_04_GPIO9_IO03,
        0x0000B0A0U);

    /* ---- 3. GPIO pin configuration -------------------------------- */
    gpio_pin_config_t ledConfig = {
        .direction     = kGPIO_DigitalOutput,
        .outputLogic   = 0U,
        .interruptMode = kGPIO_NoIntmode
    };

    GPIO_PinInit(GPIO9, 3U, &ledConfig);

    /* ---- 4. Blink loop -------------------------------------------- */
    for (;;)
    {
        GPIO_PortToggle(GPIO9, (1UL << 3U));
        SoftwareDelay(DELAY_LOOP_COUNT);
    }

    return 0;
}

