{
    /* ---- 1. Enable clock for GPIO9 -------------------------------- */
    /*
     * GPIO9 is an LPSR GPIO on RT1170.  In the MCUXpresso SDK the
     * clock-gate enum for the LPSR GPIOs is kCLOCK_Gpio9 in some SDK
     * releases.  Where only kCLOCK_Gpio is present (non-LPSR GPIO1-8)
     * we enable GPIO9's LPCG directly via its CCM LPCG register.
     *
     * RT1170 Reference Manual, Table "LPCG list":
     *   LPCG_GPIO9  base address = 0x40CC4900
     *   Bit [1:0] = 0b10 → ON (peripheral clock on, independent of CPU)
     */
    *((volatile uint32_t *)0x40CC4900U) = 0x00000002U;

    /* ---- 2. Pin mux: GPIO_AD_04 → GPIO9_IO03 ---------------------- */
    /*
     * IOMUXC_GPIO_AD_04_GPIO9_IO03 expands to the four arguments that
     * IOMUXC_SetPinMux() needs (mux register, mux mode, input register,
     * input daisy, config register).  The last argument (inputOnField)
     * is 0 because GPIO does not need a daisy-chain select.
     */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_04_GPIO9_IO03,
        0U);                        /* inputOnField = 0 */

    /*
     * Pad settings: push-pull output, moderate drive strength, no ODE.
     * 0x0000B0A0 is a common "fast GPIO output" value used in NXP
     * SDK examples for RT1170:
     *   SRE=1 (fast slew), DSE=0x6 (R0/2), ODE=0, PKE=1, PUE=1,
     *   PUS=10 (100 kΩ pull-up), HYS=0.
     */
    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_04_GPIO9_IO03,
        0x0000B0A0U);

    /* ---- 3. GPIO pin init: output, initially low (LED off) -------- */
    gpio_pin_config_t ledConfig = {
        .direction     = kGPIO_DigitalOutput,
        .outputLogic   = 0U,            /* LED off at startup           */
        .interruptMode = kGPIO_NoIntmode
    };
    GPIO_PinInit(GPIO9, 3U, &ledConfig);

    /* ---- 4. Blink loop -------------------------------------------- */
    for (;;)
    {
        GPIO_PortToggle(GPIO9, 1UL << 3U);  /* toggle pin 3             */
        SoftwareDelay(DELAY_LOOP_COUNT);    /* ~500 ms                  */
    }

    return 0;
}

