#include <stdint.h>
#include <stdbool.h>
#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_lpi2c.h"

/*******************************************************************************
 * Definitions
 ******************************************************************************/
#define LPI2C1_BASE_PTR     LPI2C1
#define SENSOR_I2C_ADDR     (0x68U)   /* 7-bit address */
#define WHO_AM_I_REG        (0x75U)
#define LPI2C1_CLOCK_HZ     (24000000U) /* OSC24M used as LPI2C1 clock source */
#define I2C_BAUDRATE_HZ     (400000U)

/*******************************************************************************
 * Prototypes
 ******************************************************************************/
static void BOARD_InitClocks(void);
static void BOARD_InitPins(void);
static status_t I2C_ReadRegister(LPI2C_Type *base,
                                  uint8_t devAddr,
                                  uint8_t regAddr,
                                  uint8_t *rxBuff,
                                  size_t rxSize);

/*******************************************************************************
 * Code
 ******************************************************************************/

/*
 * Configure the clocks needed for LPI2C1.
 *
 * LPI2C1 clock root: select OSC_RC_24M (source index 1 in the
 * CLOCK_ROOT_LPI2C1 mux on RT1170) and divide by 1 → 24 MHz.
 * The peripheral clock gate is enabled after the root is configured.
 */
static void BOARD_InitClocks(void)
{
    /* Configure LPI2C1 clock root: OSC_RC_24M / 1 = 24 MHz */
    const clock_root_config_t lpi2c1ClkCfg = {
        .clockOff = false,
        .mux      = 1U,   /* kCLOCK_LPI2C1_ClockRoot_MuxOscRc24M */
        .div      = 1U,
    };
    CLOCK_SetRootClock(kCLOCK_Root_Lpi2c1, &lpi2c1ClkCfg);

    /* Enable LPI2C1 peripheral clock gate */
    CLOCK_EnableClock(kCLOCK_Lpi2c1);
}

/*
 * Configure IOMUXC for LPI2C1 SCL (GPIO_AD_08) and SDA (GPIO_AD_09).
 *
 * ALT0 on GPIO_AD_08 = LPI2C1_SCL
 * ALT0 on GPIO_AD_09 = LPI2C1_SDA
 *
 * Both pads are configured for open-drain, fast slew rate, pull-up,
 * and high drive strength as required for 400 kHz I2C.
 *
 * IOMUXC_SetPinMux  arguments: muxRegister, muxMode, inputReg, inputDaisy, configReg, inputOnField
 * IOMUXC_SetPinConfig arguments: muxRegister, muxMode, inputReg, inputDaisy, configReg, configValue
 *
 * The input daisy (SION) bit (last arg of SetPinMux = 1) enables the
 * software-controlled input path needed for open-drain I2C lines.
 */
static void BOARD_InitPins(void)
{
    /* Clock gate for IOMUXC */
    CLOCK_EnableClock(kCLOCK_Iomuxc);

    /* GPIO_AD_08 → LPI2C1_SCL (ALT0, SION enabled) */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_08_LPI2C1_SCL,   /* mux register + mode */
        1U);                             /* SION = 1            */

    /* GPIO_AD_09 → LPI2C1_SDA (ALT0, SION enabled) */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_09_LPI2C1_SDA,
        1U);

    /*
     * Pad config word for open-drain I2C at 400 kHz:
     *   PDRV  = 0  → high drive (4 R0)
     *   PULL  = 1  → weak pull-up (47 kΩ)
     *   PUE   = 1  → pull enabled
     *   SRE   = 1  → fast slew rate
     *   ODE   = 1  → open drain
     *
     * RT1170 pad config bit-field (SW_PAD_CTL_PAD):
     *   [0]    SRE  — slew rate
     *   [3:1]  DSE  — drive strength
     *   [4]    ODE  — open drain
     *   [5]    PUE  — pull enable
     *   [6]    PUS  — pull-up/down select (1=pull-up)
     *   ...
     *
     * Use the SDK-provided bit-field macros:
     */
    uint32_t padConfig =
        IOMUXC_SW_PAD_CTL_PAD_SRE(1U)  |   /* fast slew   */
        IOMUXC_SW_PAD_CTL_PAD_DSE(1U)  |   /* drive strength R0/1 */
        IOMUXC_SW_PAD_CTL_PAD_PUE(1U)  |   /* pull enable  */
        IOMUXC_SW_PAD_CTL_PAD_PUS(1U)  |   /* pull-up      */
        IOMUXC_SW_PAD_CTL_PAD_ODE(1U);     /* open drain   */

    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_08_LPI2C1_SCL,
        padConfig);

    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_09_LPI2C1_SDA,
        padConfig);
}

/*
 * Perform a single-byte register read using the blocking LPI2C master API.
 *
 * Sequence:  START | devAddr W | regAddr | REPEATED-START | devAddr R | data | STOP
 */
static status_t I2C_ReadRegister(LPI2C_Type *base,
                                  uint8_t devAddr,
                                  uint8_t regAddr,
                                  uint8_t *rxBuff,
                                  size_t rxSize)
{
    status_t status;

    /* --- Phase 1: write the register address --- */
    lpi2c_master_transfer_t xfer = {0};
    xfer.slaveAddress   = devAddr;
    xfer.direction      = kLPI2C_Write;
    xfer.subaddress     = regAddr;
    xfer.subaddressSize = 1U;
    xfer.data           = NULL;
    xfer.dataSize       = 0U;
    xfer.flags          = kLPI2C_TransferNoStopFlag; /* keep bus active */

    status = LPI2C_MasterTransferBlocking(base, &xfer);
    if (status != kStatus_Success)
    {
        return status;
    }

    /* --- Phase 2: repeated-start then read --- */
    xfer.direction      = kLPI2C_Read;
    xfer.subaddressSize = 0U;
    xfer.data           = rxBuff;
    xfer.dataSize       = rxSize;
    xfer.flags          = kLPI2C_TransferRepeatedStartFlag; /* RS instead of START */

    status = LPI2C_MasterTransferBlocking(base, &xfer);
    return status;
}

/*******************************************************************************
 * main
 ******************************************************************************/
int main(void)
{
    /* 1. Configure clocks */
    BOARD_InitClocks();

    /* 2. Configure pin mux */
    BOARD_InitPins();

    /* 3. Initialise LPI2C1 master */
    lpi2c_master_config_t masterConfig;
    LPI2C_MasterGetDefaultConfig(&masterConfig);
    masterConfig.baudRate_Hz = I2C_BAUDRATE_HZ;

    LPI2C_MasterInit(LPI2C1_BASE_PTR, &masterConfig, LPI2C1_CLOCK_HZ);

    /* 4. Read WHO_AM_I register (0x75) from sensor at address 0x68 */
    volatile uint8_t whoAmI = 0U;
    status_t status = I2C_ReadRegister(LPI2C1_BASE_PTR,
                                        SENSOR_I2C_ADDR,
                                        WHO_AM_I_REG,
                                        (uint8_t *)&whoAmI,
                                        1U);

    /* 5. Spin forever; inspect 'whoAmI' and 'status' in the debugger */
    (void)status;
    while (1)
    {
        __asm volatile ("nop");
    }

    return 0;
}

