/*
 * Configure IOMUXC for LPI2C1 SCL (GPIO_AD_08) and SDA (GPIO_AD_09).
 *
 * ALT0 on GPIO_AD_08 = LPI2C1_SCL
 * ALT0 on GPIO_AD_09 = LPI2C1_SDA
 *
 * SION (input-on) bit set to 1 for open-drain I2C lines.
 * Pad config: open-drain, pull-up enabled, fast slew, moderate drive.
 */
static void BOARD_InitPins(void)
{
    /* Clock gate for IOMUXC */
    CLOCK_EnableClock(kCLOCK_Iomuxc);

    /* GPIO_AD_08 → LPI2C1_SCL (ALT0, SION = 1) */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_08_LPI2C1_SCL,
        1U);  /* SION */

    /* GPIO_AD_09 → LPI2C1_SDA (ALT0, SION = 1) */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_09_LPI2C1_SDA,
        1U);  /* SION */

    /*
     * Pad config for 400 kHz I2C (open-drain):
     *   SRE = 1  fast slew rate
     *   DSE = 1  drive strength
     *   ODE = 1  open drain
     *   PUE = 1  pull enable
     *   PUS = 1  pull-up select
     */
    uint32_t padConfig =
        IOMUXC_SW_PAD_CTL_PAD_SRE(1U) |
        IOMUXC_SW_PAD_CTL_PAD_DSE(1U) |
        IOMUXC_SW_PAD_CTL_PAD_PUE(1U) |
        IOMUXC_SW_PAD_CTL_PAD_PUS(1U) |
        IOMUXC_SW_PAD_CTL_PAD_ODE(1U);

    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_08_LPI2C1_SCL,
        padConfig);

    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_09_LPI2C1_SDA,
        padConfig);
}

/*
 * Read one or more bytes from a sensor register using the blocking
 * LPI2C master transfer API.
 *
 * The SDK's LPI2C_MasterTransferBlocking with direction=kLPI2C_Read and
 * a non-zero subaddressSize automatically issues:
 *   START | devAddr W | regAddr | REPEATED-START | devAddr R | data... | STOP
 */
static status_t I2C_ReadRegister(LPI2C_Type *base,
                                  uint8_t devAddr,
                                  uint8_t regAddr,
                                  uint8_t *rxBuff,
                                  size_t rxSize)
{
    lpi2c_master_transfer_t xfer;
    memset(&xfer, 0, sizeof(xfer));

    xfer.slaveAddress   = devAddr;
    xfer.direction      = kLPI2C_Read;
    xfer.subaddress     = (uint32_t)regAddr;
    xfer.subaddressSize = 1U;
    xfer.data           = rxBuff;
    xfer.dataSize       = rxSize;
    xfer.flags          = kLPI2C_TransferDefaultFlag;

    return LPI2C_MasterTransferBlocking(base, &xfer);
}

/*******************************************************************************
 * main
 ******************************************************************************/
int main(void)
{
    /* 1. Configure clocks */
    BOARD_InitClocks();

    /* 2. Configure pin mux */
    BOARD_InitPins();

    /* 3. Initialise LPI2C1 master */
    lpi2c_master_config_t masterConfig;
    LPI2C_MasterGetDefaultConfig(&masterConfig);
    masterConfig.baudRate_Hz = I2C_BAUDRATE_HZ;

    LPI2C_MasterInit(LPI2C1_BASE_PTR, &masterConfig, LPI2C1_CLOCK_HZ);

    /* 4. Read WHO_AM_I register (0x75) from sensor at address 0x68 */
    volatile uint8_t whoAmI = 0U;
    status_t status = I2C_ReadRegister(LPI2C1_BASE_PTR,
                                        SENSOR_I2C_ADDR,
                                        WHO_AM_I_REG,
                                        (uint8_t *)&whoAmI,
                                        1U);

    /* 5. Spin forever; inspect 'whoAmI' and 'status' in the debugger */
    (void)status;
    while (1)
    {
        __asm volatile ("nop");
    }

    return 0;
}

