    /* 2. Configure pin mux */
    BOARD_InitPins();

    /* 3. Initialise LPI2C1 master */
    lpi2c_master_config_t masterConfig;
    LPI2C_MasterGetDefaultConfig(&masterConfig);
    masterConfig.baudRate_Hz = I2C_BAUDRATE_HZ;

    LPI2C_MasterInit(LPI2C1, &masterConfig, LPI2C1_CLOCK_HZ);

    /* 4. Read WHO_AM_I register (0x75) from sensor at address 0x68 */
    volatile uint8_t whoAmI = 0U;
    status_t status = I2C_ReadRegister(LPI2C1,
                                        SENSOR_I2C_ADDR,
