/*
 * LPUART1 echo application for i.MX RT1170 (MIMXRT1176, Cortex-M7)
 * Pads: GPIO_AD_24 (TX), GPIO_AD_25 (RX)
 * 115200-8N1, echoes every received byte.
 *
 * Headers: fsl_common.h, fsl_clock.h, fsl_iomuxc.h, fsl_lpuart.h
 * No board.h / pin_mux.h / clock_config.h dependencies.
 */

#include <stdint.h>

#include "fsl_common.h"
#include "fsl_clock.h"
#include "fsl_iomuxc.h"
#include "fsl_lpuart.h"

/* -----------------------------------------------------------------------
 * Clock configuration
 * LPUART1 clock source: OSC_RC_48M_DIV2 (24 MHz) — always-on, no PLL needed.
 * The SDK clock selector constant is kCLOCK_Lpuart1ClkSrc.
 * ----------------------------------------------------------------------- */
#define LPUART1_CLOCK_SOURCE    (kCLOCK_Osc48MDiv2)   /* 24 MHz RC oscillator / 2 */
#define LPUART1_CLOCK_HZ        (24000000UL)

static void BOARD_InitClocks(void)
{
    /*
     * Select the clock source for LPUART1.
     * CLOCK_SetMux / CLOCK_SetDiv are the correct RT1170 SDK calls.
     * Root clock index for LPUART1 on RT1170: kCLOCK_Root_Lpuart1
     *
     * Use the unified root-clock API available in SDK 2.12+ for RT1170:
     *   CLOCK_SetRootClockMux(root, mux)
     *   CLOCK_SetRootClockDiv(root, div)
     *   CLOCK_EnableClock(kCLOCK_Lpuart1)
     *
     * Mux value 1 selects OSC_RC_48M_DIV2 (24 MHz) for LPUART roots.
     */
    clock_root_config_t lpuart1ClkCfg = {
        .clockOff = false,
        .mux      = 1U,   /* OSC_RC_48M_DIV2 = 24 MHz */
        .div      = 1U,   /* divide-by-1 → 24 MHz    */
    };
    CLOCK_SetRootClock(kCLOCK_Root_Lpuart1, &lpuart1ClkCfg);

    /* Enable the LPUART1 peripheral clock gate */
    CLOCK_EnableClock(kCLOCK_Lpuart1);
}

/* -----------------------------------------------------------------------
 * Pin-mux configuration
 *
 * GPIO_AD_24 → LPUART1_TXD   ALT0
 * GPIO_AD_25 → LPUART1_RXD   ALT0
 *
 * IOMUXC_SetPinMux(muxRegister, muxMode, inputRegister, inputDaisy, configRegister, inputOnField)
 * IOMUXC_SetPinConfig(muxRegister, muxMode, inputRegister, inputDaisy, configRegister, configValue)
 *
 * Register addresses are taken from the RT1170 reference manual / SDK
 * IOMUXC macros.  The SDK header fsl_iomuxc.h defines convenience macros
 * of the form IOMUXC_GPIO_AD_24_LPUART1_TXD etc.
 * ----------------------------------------------------------------------- */
static void BOARD_InitPins(void)
{
    /*
     * GPIO_AD_24 → LPUART1_TXD
     *   MUX register  : IOMUXC_SW_MUX_CTL_PAD_GPIO_AD_24
     *   MUX mode      : ALT0  (0U)
     *   No input-daisy select needed for TX
     *   PAD register  : IOMUXC_SW_PAD_CTL_PAD_GPIO_AD_24
     */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_24_LPUART1_TXD,   /* mux register + mode packed macro */
        0U);                              /* inputOnField: 0 = not loopback    */

    /*
     * GPIO_AD_25 → LPUART1_RXD
     *   Daisy (input select) register selects which pad drives LPUART1 RX.
     */
    IOMUXC_SetPinMux(
        IOMUXC_GPIO_AD_25_LPUART1_RXD,
        0U);

    /*
     * Pad electrical settings for both pads:
     *   - Drive strength: normal (0x2)
     *   - Slew rate: slow
     *   - Pull: 100kΩ pull-up enabled
     *
     * Bit-field layout for IOMUXC pad-control registers on RT1170:
     *   [0]    SRE  – slew rate  (0=slow)
     *   [3:1]  DSE  – drive strength (0b110 = ~43 Ω, use 0x6)
     *   [5:4]  SPEED (not present on RT1170 SW_PAD, reserved)
     *   [11]   ODE  – open drain (0=disabled)
     *   [12]   PKE  – pull/keeper enable (1=enable) [some versions]
     *   [13]   PUE  – pull vs keeper (1=pull)
     *   [15:14] PUS – pull select (10b = 100kΩ pull-up)
     *   [16]   HYS  – hysteresis (1=enable on RX)
     *
     * A safe default: 0x10B0U
     *   DSE=6(110b), SRE=0, ODE=0, PKE=1, PUE=0, PUS=0, HYS=0
     * Use a simple drive-strength-only setting; pull handled by the
     * external board for RS-232 or by the LPUART internal idle state.
     */
    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_24_LPUART1_TXD,
        0x10B0U);   /* DSE=6, fast slew, no ODE, keeper */

    IOMUXC_SetPinConfig(
        IOMUXC_GPIO_AD_25_LPUART1_RXD,
        0x10B0U);
}

/* -----------------------------------------------------------------------
 * LPUART1 initialisation — 115200-8N1
 * ----------------------------------------------------------------------- */
static void BOARD_InitLPUART(void)
{
    lpuart_config_t config;

    /* Populate defaults: 115200 baud, 8N1, no flow-control */
    LPUART_GetDefaultConfig(&config);
    config.baudRate_Bps = 115200U;
    config.dataBitsCount = kLPUART_EightDataBits;
    config.parityMode    = kLPUART_ParityDisabled;
    config.stopBitCount  = kLPUART_OneStopBit;
    config.enableTx      = true;
    config.enableRx      = true;

    status_t status = LPUART_Init(LPUART1, &config, LPUART1_CLOCK_HZ);
    /* If initialisation fails (e.g. baud-rate calculation error) spin here
     * so the issue is visible under a debugger. */
    while (status != kStatus_Success)
    {
        __NOP();
    }
}

/* -----------------------------------------------------------------------
 * Main
 * ----------------------------------------------------------------------- */
int main(void)
{
    /* 1. Clock sources */
    BOARD_InitClocks();

    /* 2. Pin mux */
    BOARD_InitPins();

    /* 3. LPUART peripheral */
    BOARD_InitLPUART();

    /* 4. Echo loop --------------------------------------------------------
     *    LPUART_ReadBlocking blocks until the requested number of bytes
     *    have been received.
     *    LPUART_WriteBlocking blocks until all bytes have been transmitted.
     * -------------------------------------------------------------------- */
    uint8_t byte;
    while (1)
    {
        /* Receive exactly one byte (blocking) */
        status_t rxStatus = LPUART_ReadBlocking(LPUART1, &byte, 1U);
        if (rxStatus == kStatus_Success)
        {
            /* Echo it back (blocking) */
            LPUART_WriteBlocking(LPUART1, &byte, 1U);
        }
        /* On framing / noise / overrun error the byte is discarded and we
         * try again — keeps the loop alive without crashing. */
    }

    /* Never reached */
    return 0;
}
